-- Initial public CityRoute Moscow place catalogue.
-- Approximate reference coordinates, NOT live Yandex venue verification.
-- No user or GPS history is written by this seed.

on conflict (id) do update set
  name = excluded.name,
  type = excluded.type,
  category = excluded.category,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  wikipedia = excluded.wikipedia,
  address = excluded.address;
